package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import java.lang.reflect.*;
import java.util.*;
import static com.ruoyi.ai.agent.AgentJson.*;

/** Real MySQL contract tests; reflection lets the first run expose the absent B1 contract. */
public class ControlledWriteTest extends TestCase {
    private A1TestFixture f; private Object service; private long workbook; private ObjectNode request;
    protected void setUp() throws Exception {
        f=new A1TestFixture();workbook=f.seed("{\"id\":\"b1\",\"sheetOrder\":[\"s\"],\"resources\":[{\"name\":\"KEEP\",\"data\":\"trusted\"}],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Orders\",\"rowCount\":20,\"columnCount\":10,\"cellData\":{\"0\":{\"0\":{\"v\":\"keep\",\"t\":1}}}}}}");
        ObjectNode ws=f.runs.workspace(workbook,1);
        request=obj().put("requestId",UUID.randomUUID().toString()).put("workbookId",workbook).put("branchId",ws.path("branchId").asLong()).put("loadedRevision",ws.path("loadedRevision").asText()).put("expectedDraftVersion",ws.path("draftVersion").asLong()).put("expectedBranchVersion",ws.path("branchVersion").asLong()).put("activeSheetId","s").put("overwrite","empty-only");
        request.set("writeScopes",arr().add(obj().put("sheetId","s").put("range","B2:C3")));
        request.set("actions",arr().add(obj().put("type","setCell").put("schemaVersion","1.0").put("sheetId","s").put("range","B2").put("value",11)));
        Class<?> type;
        try{type=Class.forName("com.ruoyi.ai.agent.ControlledWriteService");}catch(ClassNotFoundException absent){fail("B1 controlled-write contract is absent");return;}
        service=type.getConstructor(AgentStore.class,AgentWriteGuard.class,com.ruoyi.ai.mapper.AiWorkbookMapper.class,com.ruoyi.ai.mapper.WorkbookVersionMapper.class,org.springframework.transaction.PlatformTransactionManager.class)
            .newInstance(new AgentStore(f.db),f.guard,f.workbooks,f.versions,f.tx.getTransactionManager());
        A1TestFixture.inject(service,"enabled",true);
    }
    private ObjectNode invoke(String name,Class<?>[] types,Object... args){try{return (ObjectNode)service.getClass().getMethod(name,types).invoke(service,args);}catch(InvocationTargetException e){if(e.getCause() instanceof RuntimeException)throw (RuntimeException)e.getCause();throw new RuntimeException(e.getCause());}catch(Exception e){throw new RuntimeException(e);}}
    private ObjectNode create(ObjectNode req){return invoke("create",new Class[]{ObjectNode.class,long.class},req,1L);}
    private ObjectNode claim(ObjectNode run){return invoke("claim",new Class[]{String.class,long.class,ObjectNode.class},run.path("runId").asText(),1L,obj().put("clientId","test-client").put("fencingToken",run.path("fencingToken").asLong()));}
    private ObjectNode receipt(ObjectNode run,ObjectNode req){return invoke("receipt",new Class[]{String.class,long.class,ObjectNode.class},run.path("runId").asText(),1L,req);}
    private ObjectNode ok(ObjectNode manifest){ObjectNode r=obj().put("transportVersion",2).put("callId",manifest.path("callId").asText()).put("claimToken",manifest.path("claimToken").asText()).put("argsHash",manifest.path("argsHash").asText()).put("fencingToken",manifest.path("fencingToken").asLong()).put("ok",true);ArrayNode cells=arr();for(com.fasterxml.jackson.databind.JsonNode expected:manifest.path("cells")){ObjectNode c=obj().put("sheetId",expected.path("sheetId").asText()).put("row",expected.path("row").asInt()).put("column",expected.path("column").asInt()).put("formula","");c.set("value",expected.path("value"));cells.add(c);}r.set("cells",cells);return r;}
    private void reject(Runnable action){try{action.run();fail("Unsafe controlled write accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testSetCellUsesTrustedPatchAndCas(){ObjectNode run=create(request),m=claim(run);ObjectNode result=receipt(run,ok(m));assertEquals("COMPLETED",result.path("status").asText());assertEquals("SAVED",result.path("persistenceStatus").asText());ObjectNode saved=(ObjectNode)parse((String)f.status(workbook).get("content"));assertEquals(11,saved.path("sheets").path("s").path("cellData").path("1").path("1").path("v").asInt());assertEquals("trusted",saved.path("resources").get(0).path("data").asText());}
    public void testV2MatrixAndLegacyTargetCompatibility(){ObjectNode a=obj().put("type","setValues").put("schemaVersion","2.0");a.set("target",obj().put("sheetId","s").put("range","B2:C3"));a.set("values",parse("[[1,2],[3,4]]"));request.set("actions",arr().add(a));ObjectNode run=create(request);ObjectNode result=receipt(run,ok(claim(run)));assertEquals("COMPLETED",result.path("status").asText());assertEquals(0,((Number)((Map<?,?>)f.status(workbook).get("workingState")).get("version")).intValue());}
    public void testInvalidV2TargetCreatesNoWriteOrLease(){((ObjectNode)request.path("actions").get(0)).put("schemaVersion","2.0");reject(()->create(request));assertNull(f.status(workbook).get("workingState"));assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_lease where workbook_id=? and run_id is not null",Integer.class,workbook).intValue());}
    public void testOutOfScopeActionRejectedBeforeExecution(){((ObjectNode)request.path("actions").get(0)).put("range","A1");reject(()->create(request));assertNull(f.status(workbook).get("workingState"));}
    public void testExtraCellReceiptAndWrongValueRejected(){ObjectNode run=create(request),m=claim(run),r=ok(m);((ArrayNode)r.path("cells")).add(obj().put("sheetId","s").put("row",0).put("column",0).put("value","hacked").put("formula",""));final ObjectNode extra=r;reject(()->receipt(run,extra));r=ok(m);((ObjectNode)r.path("cells").get(0)).put("value",99);final ObjectNode wrong=r;reject(()->receipt(run,wrong));assertNull(f.status(workbook).get("workingState"));}
    public void testSnapshotResourcesInjectionNeverPersisted(){ObjectNode run=create(request),m=claim(run),r=ok(m);r.set("snapshot",parse("{\"resources\":[{\"name\":\"KEEP\",\"data\":\"hacked\"}]}"));reject(()->receipt(run,r));assertNull(f.status(workbook).get("workingState"));}
    public void testDuplicateCreateClaimAndReceiptDoNotReapply(){ObjectNode run=create(request);assertEquals(run.path("runId"),create(request).path("runId"));ObjectNode m=claim(run);assertFalse(claim(run).has("actions"));ObjectNode r=ok(m);receipt(run,r);receipt(run,r);assertEquals(0,((Number)((Map<?,?>)f.status(workbook).get("workingState")).get("version")).intValue());ObjectNode other=request.deepCopy();other.put("overwrite","confirmed");reject(()->create(other));}
    public void testBrowserFailureIsUnknownNotCompleted(){ObjectNode run=create(request),r=ok(claim(run));r.put("ok",false);r.remove("cells");ObjectNode result=receipt(run,r);assertEquals("PAUSED",result.path("status").asText());assertNull(f.status(workbook).get("workingState"));reject(()->claim(run));}
    public void testLostVersionCannotOverwriteExternalDraft(){ObjectNode run=create(request),m=claim(run);f.db.update("insert into ai_workbook_working_state(workbook_id,branch_id,owner_user_id,base_commit_id,draft_actions_json,executed_changes_json,draft_snapshot,content_hash,version,update_time) values(?,?,1,null,'[]','[]',?,?,0,now(3))",workbook,request.path("branchId").asLong(),"{\"external\":true}".getBytes(java.nio.charset.StandardCharsets.UTF_8),com.ruoyi.ai.util.ContentHashUtils.sha256("{\"external\":true}"));reject(()->receipt(run,ok(m)));assertEquals("{\"external\":true}",f.status(workbook).get("content"));}
    public void testDisabledFeatureNeverBypassesActiveLeaseOrBlocksCancellation()throws Exception{ObjectNode run=create(request);A1TestFixture.inject(service,"enabled",false);reject(()->f.save(workbook,f.request(workbook,-1,request.path("loadedRevision").asText(),"{}")));assertEquals("CANCELLED",f.runs.cancel(run.path("runId").asText(),1).path("status").asText());}
    public void testEmptyDefaultPermissionResourcesAreCompatible(){ObjectNode snapshot=(ObjectNode)parse(String.valueOf(f.status(workbook).get("content")));snapshot.set("resources",arr().add(obj().put("name","SHEET_RANGE_PROTECTION_PLUGIN").put("data","")).add(obj().put("name","SHEET_WORKSHEET_PROTECTION_PLUGIN").put("data","{}")));assertEquals(1,WriteManifest.create(snapshot,request.path("actions"),request.path("writeScopes"),"s","empty-only",false).path("cells").size());}
    public void testActualOrMalformedPermissionsRemainBlocked(){ObjectNode snapshot=(ObjectNode)parse(String.valueOf(f.status(workbook).get("content")));for(String data:Arrays.asList("{\"s\":{\"permissionId\":\"protected\"}}","not-json","null")){snapshot.set("resources",arr().add(obj().put("name","SHEET_WORKSHEET_PROTECTION_PLUGIN").put("data",data)));reject(()->WriteManifest.create(snapshot,request.path("actions"),request.path("writeScopes"),"s","confirmed",true));}}
    public void testUnclaimedCancellationClosesCallLedgerWithoutWriting(){ObjectNode run=create(request);assertEquals("CANCELLED",f.runs.cancel(run.path("runId").asText(),1).path("status").asText());assertEquals("CANCELLED",f.db.queryForObject("select status from ai_agent_tool_call where run_id=?",String.class,run.path("runId").asText()));assertNull(f.status(workbook).get("workingState"));reject(()->claim(run));}
}
